sp_widget.css:
.metric-card{

background:#FFFFFF;

height:190px;

border-radius:28px;

padding:26px;

position:relative;

overflow:hidden;

box-shadow:
0 14px 40px rgba(0,0,0,.06);

display:flex;

flex-direction:column;

justify-content:center;

}

/* top row */
.top{

display:flex;

align-items:center;

gap:24px;

position:relative;

z-index:2;

}

/* colored left border */
.department{
border-left:5px solid #08B77B;
}

.active{
border-left:5px solid #FDB022;
}

.inactive{
border-left:5px solid #A259FF;
}

/* icon */
.metric-icon{

width:78px;

height:78px;

min-width:78px;

border-radius:22px;

display:flex;

align-items:center;

justify-content:center;

font-size:34px;

}

.department .metric-icon{
background:#DCF8EA;
}

.active .metric-icon{
background:#FFF2D8;
}

.inactive .metric-icon{
background:#F2E8FF;
}

/* right section */

.metric-info{

display:flex;

flex-direction:column;

justify-content:center;

}

.metric-value{

font-size:62px;

font-weight:900;

color:#07195A;

line-height:1;

margin-bottom:8px;

}

.metric-title{

font-size:22px;

font-weight:800;

color:#6D7CA7;

}

.metric-sub{

margin-left:102px;

margin-top:6px;

font-size:14px;

color:#9AA5C2;

position:relative;

z-index:2;

}

/* decorative circle */

.bg-circle{

position:absolute;

right:-55px;

bottom:-55px;

width:170px;

height:170px;

border-radius:50%;

opacity:.08;

}

.department .bg-circle{
background:#00B87A;
}

.active .bg-circle{
background:#FFB020;
}

.inactive .bg-circle{
background:#A259FF;
}

sp_widget.script:
(function() {

data.total = 0;

var gr =
new GlideAggregate(
'x_1902481_employ_0_employee'
);

gr.addQuery(
'status',
'inactive'
);

gr.addAggregate(
'COUNT'
);

gr.query();

if(gr.next()){

data.total =
parseInt(
gr.getAggregate('COUNT'),
10
);

}

})();
